    /// <summary>
    /// Returns the list of stories added to the given story album. For optimal performance, the number of returned stories is chosen by TDLib
    /// </summary>
    public Task<TdLib.TdApi.Objects.Stories> GetStoryAlbumStoriesAsync(long chatId = default, int storyAlbumId = default, int offset = default, int limit = default)
    {

           using var activity =  StartCallActivity("GetStoryAlbumStoriesAsync", typeof(GetStoryAlbumStories).FullName ?? "GetStoryAlbumStoriesAsync");

           try
           {
             return client.GetStoryAlbumStoriesAsync(chatId, storyAlbumId, offset, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
